```ds
package algos

fn is_prime(n: i32) -> bool {
    if n < 2 { return false }
    var i = 2
    while i * i <= n {
        if n % i == 0 { return false }
        i = i + 1
    }
    true
}

fn main() {
    for n in range(2, 60) {
        if is_prime(n) { print(str(n) + " ") }
    }
    println("")
}
```

