```ds
package algos

fn bsearch(xs: [i32], target: i32) -> i32 {
    var lo = 0
    var hi = len(xs) - 1
    while lo <= hi {
        let mid = (lo + hi) / 2
        if xs[mid] == target { return mid }
        if xs[mid] < target { lo = mid + 1 } else { hi = mid - 1 }
    }
    -1
}

fn main() {
    println(bsearch([1 3 5 7 9], 7))
}
```

